function renderReliability(value){const metrics=$('#reliability-metrics'),failures=$('#reliability-failures');metrics.replaceChildren();failures.replaceChildren();if(!value)return empty(metrics,'Reliability data is not available yet.');const model=value.model||{};const cards=[['Model',model.state==='ready'?`Connected · ${model.activeModel}`:model.state.replaceAll('_',' ')],['Chat success',value.chat.successRate===null?'No conversations yet':`${value.chat.successRate}% (${value.chat.successful}/${value.chat.successful+value.chat.failed})`],['Background work',`${value.background.successful} completed · ${value.background.failed} failed`],['Needs approval',String(value.pendingApprovals)]];for(const [label,result] of cards){const card=document.createElement('article');card.className='panel metric-card';const small=document.createElement('p');small.className='eyebrow';small.textContent=label;const strong=document.createElement('strong');strong.textContent=result;card.append(small,strong);metrics.append(card);}if(!value.recentFailures.length)return empty(failures,'No failures recorded in the last seven days.');for(const failure of value.recentFailures){const card=document.createElement('article');card.className='item-card';const h=document.createElement('h3');h.textContent=failure.message;const p=document.createElement('p');p.textContent=`${failure.type.replaceAll('_',' ')} · ${formatDate(failure.created_at)}`;card.append(h,p);failures.append(card);}}
function renderPreferences(value){if(!value)return;const form=$('#preferences-form');if(preferencesDirty||form.contains(document.activeElement))return;$('#preference-timezone').value=value.time_zone||'America/New_York';$('#preference-quiet-start').value=value.quiet_start||'22:00';$('#preference-quiet-end').value=value.quiet_end||'08:00';$('#preference-proactive').checked=value.proactive_enabled!==0;}
function renderModelStatus(value){const grid=$('#safety .settings-grid');if(!grid)return;let panel=$('#model-health');if(!panel){panel=document.createElement('section');panel.id='model-health';panel.className='panel';grid.prepend(panel);}panel.replaceChildren();const heading=document.createElement('h2');heading.textContent='AI model connection';const status=document.createElement('p');status.className='muted';const state=value?.state||'demo';const labels={demo:'Demo mode — no API key connected.',unverified:'Configured, waiting for a connection check.',ready:`Connected to ${value?.activeModel||value?.primaryModel}.`,fallback:`${value?.primaryModel} is unavailable; safely using ${value?.activeModel}.`,authentication:'The existing Render API key was rejected or has been revoked.',quota:'API credits or the project spending limit need attention.',rate_limit:'The model is temporarily rate-limited.',model_access:value?.availableTextModelCount===0?'The key works, but this OpenAI project reports no text-generation models. Check project model permissions and billing.':'The key works, but this OpenAI project cannot access Orbit’s configured or compatible models.',network:'Render could not reach the OpenAI API.',service:'The OpenAI service is temporarily unavailable.',request:'OpenAI rejected the connection check.'};status.textContent=labels[state]||'Model status is unknown.';panel.append(heading,status);const meta=document.createElement('div');meta.className='meta';for(const label of [`primary: ${value?.primaryModel||'not set'}`,`fallback: ${(value?.fallbackModels||[value?.fallbackModel]).filter(Boolean).join(', ')||'not set'}`,`state: ${state.replaceAll('_',' ')}`,value?.availableTextModelCount===null||value?.availableTextModelCount===undefined?null:`available text models: ${value.availableTextModelCount}`].filter(Boolean)){const tag=document.createElement('span');tag.className='badge';tag.textContent=label;meta.append(tag);}panel.append(meta);if(value?.lastError){const detail=document.createElement('p');detail.className='hint block-top';detail.textContent=value.lastError;panel.append(detail);}panel.append(button('Check connection','ghost block-top',checkModelConnection));}
function renderActivity(items){const root=$('#activity-list');root.replaceChildren();if(!items.length)return empty(root,'Activity will appear here.');for(const event of items){const el=document.createElement('div');el.className='timeline-item';const p=document.createElement('p');p.textContent=event.message;const time=document.createElement('time');time.dateTime=event.created_at;time.textContent=formatDate(event.created_at);el.append(p,time);root.append(el);}}
function renderFiles(items){const root=$('#files-list');root.replaceChildren();if(!items.length)return empty(root,'Completed task files will appear here.');for(const file of items){const card=document.createElement('article');card.className='item-card';const head=document.createElement('header');const wrap=document.createElement('div');const h=document.createElement('h3');h.textContent=file.name;const p=document.createElement('p');p.textContent=`${Math.max(1,Math.round(file.size_bytes/1024))} KB · ${formatDate(file.created_at)}`;wrap.append(h,p);const link=document.createElement('a');link.className='primary link-button';link.href=`/api/artifacts/${file.id}`;link.textContent='Download';head.append(wrap,link);card.append(head);root.append(card);}}
function renderConnections(){const root=$('#connections-list');if(!root||!state.snapshot)return;const ae=document.activeElement;if(ae&&ae.tagName==='INPUT'&&root.contains(ae))return;root.replaceChildren();const connected=new Map((state.snapshot.connectors||[]).map((item)=>[item.provider,item]));for(const provider of state.status.connectors||[]){const card=document.createElement('article');card.className='panel connector-card';const h=document.createElement('h2');h.textContent=provider.label;const p=document.createElement('p');p.className='muted';const live=connected.has(provider.id);p.textContent=live?'Connected with encrypted credentials.':provider.configured?'Ready to connect.':'Server administrator must configure OAuth credentials.';card.append(h,p);if(live){const actions=document.createElement('div');actions.className='mini-actions';actions.append(button('Preview access','ghost',()=>previewConnector(provider.id)),button('Disconnect','danger',()=>disconnectConnector(provider.id)));card.append(actions);}else{const connect=button('Connect','primary',()=>beginConnector(provider.id));connect.disabled=!provider.configured;card.append(connect);}root.append(card);}renderCalendarFeeds();}
function renderCalendarFeeds(){const root=$('#connections-list');if(!root||!state.snapshot)return;const feeds=state.snapshot.calendarFeeds||[];const panel=document.createElement('section');panel.className='panel section-gap';const h=document.createElement('h2');h.textContent='Calendar feeds';panel.append(h);const p=document.createElement('p');p.className='muted';p.textContent='Connect iCal feeds (Google, Apple, Outlook) so Orbit can read your schedule. Feed URLs are secret \u2014 only a masked preview is ever shown.';panel.append(p);const list=document.createElement('div');list.className='card-list block-top';if(!feeds.length){const e=document.createElement('p');e.className='muted';e.textContent='No calendars connected yet.';list.append(e);}for(const feed of feeds){const card=document.createElement('article');card.className='item-card';const head=document.createElement('header');const wrap=document.createElement('div');const title=document.createElement('h3');title.textContent=feed.label;const url=document.createElement('p');url.className='muted';url.textContent=feed.url;wrap.append(title,url);head.append(wrap,button('Remove','danger',()=>removeCalendarFeed(feed.id,feed.label)));card.append(head);list.append(card);}panel.append(list);const form=document.createElement('div');form.className='form-grid block-top';const labelWrap=document.createElement('label');labelWrap.textContent='Label';const labelInput=document.createElement('input');labelInput.placeholder='e.g. School';labelInput.maxLength=60;labelWrap.append(labelInput);const urlWrap=document.createElement('label');urlWrap.textContent='iCal feed URL';const urlInput=document.createElement('input');urlInput.placeholder='https://\u2026';urlInput.inputMode='url';urlInput.autocomplete='off';urlWrap.append(urlInput);const addBtn=button('Add calendar','primary',async()=>{const label=labelInput.value.trim(),feedUrl=urlInput.value.trim();if(!label||!feedUrl){toast('A label and feed URL are both required.');return;}addBtn.disabled=true;try{const added=await api('/api/calendar-feeds',{method:'POST',body:JSON.stringify({label,url:feedUrl})});toast(`Connected \u201c${added.feed.label}\u201d \u2014 ${added.eventsFound} events found.`);await refresh();}catch(error){toast(error.message);}finally{addBtn.disabled=false;}});form.append(labelWrap,urlWrap,addBtn);panel.append(form);const hint=document.createElement('p');hint.className='hint';hint.textContent='Google Calendar: Settings \u2192 pick the calendar \u2192 Secret address in iCal format. Apple Calendar: publish/share the calendar and copy its subscription link.';panel.append(hint);root.append(panel);}
async function removeCalendarFeed(id,label){if(!window.confirm(`Remove the \u201c${label}\u201d calendar feed?`))return;try{await api(`/api/calendar-feeds/${id}`,{method:'DELETE'});await refresh();toast('Calendar feed removed.');}catch(error){toast(error.message);}}
function render(){if(!state.snapshot)return;renderThreads();settlePendingReplies(state.snapshot.messages||[],state.snapshot.activeConversation&&state.snapshot.activeConversation.id);renderMessages(state.snapshot.messages);syncTypingBubble();syncStreamPoller();renderTodayFocus(state.snapshot.goals||[],state.snapshot.routines||[]);renderGoals(state.snapshot.goals||[]);renderRoutines(state.snapshot.routines||[]);renderProjects(state.snapshot.projects||[]);renderApprovals(state.snapshot.approvals||[],state.snapshot.tasks||[]);renderReliability(state.snapshot.reliability);renderTasks(state.snapshot.tasks);renderFiles(state.snapshot.artifacts||[]);renderMemories(state.snapshot.memories,state.snapshot.memorySuggestions);renderFollowUps(state.snapshot.followUps||[]);renderPreferences(state.snapshot.preferences);renderModelStatus(state.status.modelStatus);renderActivity(state.snapshot.events);renderConnections();const paused=state.status.paused;$('#pause-banner').classList.toggle('hidden',!paused);$('#pause-button').classList.toggle('hidden',paused);$('#resume-button').classList.toggle('hidden',!paused);$('#chat-input').disabled=paused;const isOwner=state.user&&state.user.role==='owner';$('#registration-panel').classList.toggle('hidden',!isOwner);if(isOwner){const open=!!state.setup?.registrationOpen;$('#registration-status').textContent=open?'Registration is open. New signups can create accounts.':'Registration is closed. New signups are turned away.';$('#registration-toggle').textContent=open?'Close':'Open';$('#registration-toggle').classList.toggle('danger',open);}$('#access-panel').classList.toggle('hidden',!isOwner);if(isOwner)renderAccessRequests();}
function renderThreads(){const bar=document.querySelector('#thread-bar');if(!bar||!state.snapshot)return;bar.replaceChildren();for(const c of state.snapshot.conversations||[]){const b=document.createElement('button');b.type='button';b.className='thread-chip'+(c.id===activeConversationId?' active':'');const label=document.createElement('span');label.className='thread-label';label.textContent=c.title;b.append(label);const x=document.createElement('span');x.className='thread-x';x.textContent='\u00d7';x.title='Delete this conversation';x.addEventListener('click',(ev)=>{ev.stopPropagation();deleteThread(c.id,c.title);});b.append(x);b.addEventListener('click',()=>{if(c.id!==activeConversationId){activeConversationId=c.id;try{localStorage.setItem('orbit-convo',c.id);}catch(_){}refresh().catch(()=>{});}});bar.append(b);}const n=document.createElement('button');n.type='button';n.className='thread-chip thread-new';n.textContent='+ New chat';n.addEventListener('click',newThread);bar.append(n);}
